import 'dart:convert';

import '../../../models/slide_model.dart';

// Generated from the user-provided offline scene HTML files.
// Keep the sources embedded so exported presentations remain self-contained.
String presentationBackgroundSceneHtml(PresentationBackgroundKind kind) {
  return _decodedBackgroundScenes.putIfAbsent(
    kind,
    () =>
        _lightBackgroundSceneHtml(kind) ??
        utf8.decode(base64Decode(_backgroundSceneBase64[kind]!)),
  );
}

final Map<PresentationBackgroundKind, String> _decodedBackgroundScenes =
    <PresentationBackgroundKind, String>{};

String? _lightBackgroundSceneHtml(PresentationBackgroundKind kind) {
  switch (kind) {
    case PresentationBackgroundKind.lightCorporate:
      return _buildLightScene(
        title: 'Açık Kurumsal',
        motif: 'corporate',
        background: '#F8FBFF',
        surface: '#E7F0FF',
        accent: '#4F7DF3',
        accentSoft: 'rgba(79, 125, 243, 0.16)',
      );
    case PresentationBackgroundKind.lightEducation:
      return _buildLightScene(
        title: 'Açık Eğitim',
        motif: 'education',
        background: '#FFFEF8',
        surface: '#FFF2C7',
        accent: '#E6A72F',
        accentSoft: 'rgba(230, 167, 47, 0.17)',
      );
    case PresentationBackgroundKind.lightNature:
      return _buildLightScene(
        title: 'Açık Doğa',
        motif: 'nature',
        background: '#F7FFF9',
        surface: '#DDF5E6',
        accent: '#45A675',
        accentSoft: 'rgba(69, 166, 117, 0.16)',
      );
    case PresentationBackgroundKind.lightTechnology:
      return _buildLightScene(
        title: 'Açık Teknoloji',
        motif: 'technology',
        background: '#F7FCFF',
        surface: '#DDF5FA',
        accent: '#168D9A',
        accentSoft: 'rgba(22, 141, 154, 0.15)',
      );
    case PresentationBackgroundKind.lightCreative:
      return _buildLightScene(
        title: 'Açık Yaratıcı',
        motif: 'creative',
        background: '#FFFAFD',
        surface: '#F6E6FF',
        accent: '#A64FD2',
        accentSoft: 'rgba(166, 79, 210, 0.15)',
      );
    case PresentationBackgroundKind.lightWarm:
      return _buildLightScene(
        title: 'Açık Sıcak',
        motif: 'warm',
        background: '#FFFBF5',
        surface: '#FFE6D5',
        accent: '#D97048',
        accentSoft: 'rgba(217, 112, 72, 0.15)',
      );
    default:
      return null;
  }
}

String _buildLightScene({
  required String title,
  required String motif,
  required String background,
  required String surface,
  required String accent,
  required String accentSoft,
}) =>
    '''
<!DOCTYPE html>
<html lang="tr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Sutol — $title</title>
<style>
:root{--bg:$background;--surface:$surface;--accent:$accent;--accent-soft:$accentSoft}
*{box-sizing:border-box}html,body{width:100%;height:100%;margin:0;overflow:hidden;background:var(--bg)}
.sutol-scene{position:relative;width:100%;height:100%;overflow:hidden;background:linear-gradient(135deg,var(--bg),var(--surface))}
.wash{position:absolute;inset:-20%;background:radial-gradient(circle at 78% 22%,var(--accent-soft),transparent 28%),radial-gradient(circle at 14% 82%,var(--accent-soft),transparent 24%);animation:wash 16s ease-in-out infinite alternate}
.grid{position:absolute;inset:0;opacity:.34;background-image:linear-gradient(rgba(80,96,120,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(80,96,120,.07) 1px,transparent 1px);background-size:64px 64px;mask-image:linear-gradient(110deg,transparent 5%,#000 48%,transparent 95%)}
.orb{position:absolute;border-radius:50%;background:var(--accent-soft);filter:blur(1px);animation:float 15s ease-in-out infinite alternate}
.orb.a{width:28vmax;height:28vmax;right:-10vmax;top:-12vmax}.orb.b{width:17vmax;height:17vmax;left:-7vmax;bottom:-8vmax;animation-duration:19s;animation-direction:alternate-reverse}
.motif{position:absolute;inset:0;color:var(--accent)}.motif i{position:absolute;display:block;opacity:.42;animation:drift 12s ease-in-out infinite alternate}
.motif i:nth-child(1){left:66%;top:17%;animation-delay:-2s}.motif i:nth-child(2){left:82%;top:52%;animation-delay:-7s}.motif i:nth-child(3){left:57%;top:73%;animation-delay:-4s}.motif i:nth-child(4){left:16%;top:69%;animation-delay:-9s}.motif i:nth-child(5){left:28%;top:14%;animation-delay:-6s}.motif i:nth-child(6){left:44%;top:42%;animation-delay:-1s}
.corporate i{width:clamp(44px,6vw,110px);height:clamp(44px,6vw,110px);border:1px solid currentColor;border-radius:50%}.corporate i:nth-child(even){border-style:dashed}
.education i{width:clamp(18px,2.2vw,38px);height:clamp(18px,2.2vw,38px);border:2px solid currentColor;border-radius:8px;transform:rotate(12deg)}.education i:nth-child(even){border-radius:50%;transform:rotate(-8deg)}
.nature i{width:clamp(28px,4vw,72px);height:clamp(14px,2vw,36px);border-radius:100% 0 100% 0;background:var(--accent-soft);border:1px solid currentColor;transform:rotate(-24deg)}.nature i:nth-child(even){transform:rotate(38deg)}
.technology i{width:clamp(70px,10vw,180px);height:1px;background:currentColor;transform-origin:left center}.technology i:before,.technology i:after{content:"";position:absolute;top:50%;width:8px;height:8px;border:2px solid currentColor;border-radius:50%;background:var(--bg);transform:translateY(-50%)}.technology i:before{left:0}.technology i:after{right:0}.technology i:nth-child(even){transform:rotate(32deg)}
.creative i{width:clamp(32px,5vw,88px);height:clamp(32px,5vw,88px);border-radius:30% 70% 62% 38%;background:var(--accent-soft);border:1px solid currentColor;animation-name:drift,shape;animation-duration:12s,18s}.creative i:nth-child(even){border-radius:50%;background:transparent}
.warm i{width:clamp(55px,8vw,140px);height:clamp(28px,4vw,70px);border:2px solid currentColor;border-bottom:0;border-radius:140px 140px 0 0;opacity:.30}.warm i:nth-child(even){transform:rotate(180deg)}
@keyframes wash{to{transform:translate3d(3%,-2%,0) scale(1.04)}}
@keyframes float{to{transform:translate3d(-2.5vw,2vh,0) scale(1.07)}}
@keyframes drift{to{translate:1.8vw -2.2vh;rotate:7deg;opacity:.62}}
@keyframes shape{50%{border-radius:70% 30% 38% 62%}}
@media(prefers-reduced-motion:reduce){.wash,.orb,.motif i{animation:none!important}}
</style>
</head>
<body>
<div class="sutol-scene sutol-light-scene sutol-light-$motif">
  <div class="wash"></div><div class="grid"></div>
  <div class="orb a"></div><div class="orb b"></div>
  <div class="motif $motif"><i></i><i></i><i></i><i></i><i></i><i></i></div>
</div>
</body>
</html>
''';

const Map<PresentationBackgroundKind, String> _backgroundSceneBase64 =
    <PresentationBackgroundKind, String>{
  PresentationBackgroundKind.science:
      '',
  PresentationBackgroundKind.biology:
      '',
  PresentationBackgroundKind.natureEcology:
      '',
  PresentationBackgroundKind.physics:
      '',
  PresentationBackgroundKind.solarEnergyScene:
      '',
  PresentationBackgroundKind.lawJustice:
      '',
  PresentationBackgroundKind.climateWeather:
      '',
  PresentationBackgroundKind.businessFinance:
      '',
  PresentationBackgroundKind.chemistry:
      '',
  PresentationBackgroundKind.mathematics:
      '',
  PresentationBackgroundKind.musicSound:
      '',
  PresentationBackgroundKind.optics:
      '',
  PresentationBackgroundKind.healthMedicine:
      '',
  PresentationBackgroundKind.artDesign:
      '',
  PresentationBackgroundKind.travelGeography:
      '',
  PresentationBackgroundKind.sportsMovement:
      '',
  PresentationBackgroundKind.historyArchaeology:
      '',
  PresentationBackgroundKind.technology:
      '',
  PresentationBackgroundKind.spaceTechnology:
      '',
};
